// server.js, first import of the file, before anything reads process.env.
import 'dotenv/config';
import express from 'express';

const port = Number(process.env.PORT) || 3000;
const app = express();

app.get('/api/health', (request, response) => {
  // Show which database the process will use, never the password.
  response.json({ ok: true, db: process.env.DB_NAME });
});

app.listen(port, () => console.log(`http://localhost:${port}`));

// Convert once, at the edge, then export typed values.
const port = Number(process.env.PORT || 3000);
const debug = process.env.DEBUG === 'true';   // "false" is a truthy string

if (Number.isNaN(port)) {
  throw new Error('PORT must be a number');
}

console.log({ port, debug, nodeEnv: process.env.NODE_ENV });

import express from 'express';
import cors from 'cors';

